<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Grid, List, TrendCharts, Document, Setting, Cpu, ArrowDown, ArrowRight, Fold, Select, Operation, DataAnalysis } from '@element-plus/icons-vue'
import GameIcon from './components/GameIcon.vue'
import ReportCard from './components/ReportCard.vue'
import ResearchLeadList from './components/ResearchLeadList.vue'
import SourceCandidates from './components/SourceCandidates.vue'
import IdentityWorkspace from './components/IdentityWorkspace.vue'
import ResearchWorkspace from './components/ResearchWorkspace.vue'
import GameProfile from './components/GameProfile.vue'
import CollectionCatalog from './components/CollectionCatalog.vue'
import CaptureWorkspace from './components/CaptureWorkspace.vue'
import { getProfileProducts, workspaceAccess, loginWorkspace } from './api'
import { createSelection, getProduct, getProducts, getRankings, getSelections, getAiConfig, saveAiConfig, getLatestReport, getReport, getReportHistory, getReportSkill, getInsightCollection, runInsightCollection, generateReport, getMarketRankings, getCurrentRule, getCoverage, publishRule, getStats, getPublicRankings, type Product, type Ranking } from './api'
const productView=ref('sources')
const active=ref('overview'),collapsed=ref(false),loading=ref(false),error=ref('')
const groups=reactive<Record<string,boolean>>({'实际使用':true,'配置管理':true})
const filters=reactive({q:'',platform:'',region:'',poolState:'',selectionState:'',qualification:'',gap:'',chartId:'',date:'',page:1})
const profileScope=reactive({product:'',listing:'',version:'',market:'',date:'',tab:'overview'})
const accessReady=ref(false),authenticated=ref(false),accessError=ref(''),loginToken=ref(''),loginBusy=ref(false),loginError=ref('')
const productCharts=computed(()=>(coverage.value.charts||[]).filter((c:any)=>!c.external&&c.platform===filters.platform&&c.region===filters.region))
let returnUrl='#/products'
const data=ref<any>({date:'',total:0,items:[]}),stats=ref<any>({}),coverage=ref<any>({charts:[]})
const dossierStats=ref<any>(null),dossierStatsError=ref(''),dossierStatsBusy=ref(false)
const charts=ref<any[]>([]),selectedChart=ref(''),chartPlatform=ref(''),chartType=ref(''),rankingData=ref<any>({items:[]}),selectionData=ref<any>({items:[]})
const reportData=ref<any>({items:[],message:'尚未生成周报'}),reportGroup=ref('ALL')
const reportHistory=ref<any>({items:[],total:0}),historyPage=ref(1),historyOpen=ref(false),reportId=ref(''),generating=ref(false)
const exporting=ref(false)
const historyLoading=ref(false),historyError=ref(''),openingReport=ref(''),reportAction=ref(''),reportActionError=ref(false)
let historyRequest=0,reportRequest=0
const researchCount=computed(()=>reportData.value.researchLeads?.items?.length||0)
const visibleResearchCount=computed(()=>(reportData.value.researchLeads?.items||[]).filter((r:any)=>reportGroup.value==='ALL'||(reportGroup.value==='DOMESTIC'?r.region==='CN':r.region!=='CN')).length)
const reportSummary=computed(()=>reportData.value.id?`报告 #${reportData.value.id} · 修订 ${reportData.value.revision}，已保存 ${researchCount.value} 条待核研究线索、${reportData.value.items?.length||0} 条正式候选`:'尚未生成报告')
const skillOpen=ref(false),skillData=ref<any>(null),collectionStatus=ref<any>(null),collecting=ref(false),auditPage=ref(1)
const reportCoverage=computed(()=>{try{return typeof reportData.value.coverage==='string'?JSON.parse(reportData.value.coverage):reportData.value.coverage||{}}catch{return {}}})
const generatedTime=computed(()=>{const raw=reportData.value.generatedAt;if(!raw)return '—';const value=String(raw);return new Date(value+(value.endsWith('Z')?'':'Z')).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+'（北京时间）'})
const auditRows=computed(()=>(reportData.value.candidateAudit||[]).slice((auditPage.value-1)*20,auditPage.value*20))
const decisionLabel:Record<string,string>={SELECTED:'入选',LIMIT_OR_DIVERSITY:'限额 / 多样性',DUPLICATE_PRODUCT:'同产品去重',GAMEPLAY_UNVERIFIED:'玩法未核验',COMPLEX_GAMEPLAY_REVIEW:'复杂玩法需核验',INSUFFICIENT_SIGNAL:'市场信号不足',ALREADY_PRODUCING:'制作中 / 已完成',MANUALLY_EXCLUDED:'人工排除'}
const aiConfig=reactive({providerName:'',baseUrl:'',model:'',apiKey:'',apiKeyConfigured:false,timeoutSeconds:60,temperature:0.2,enabled:false})
const ruleData=reactive({versionNumber:0,rulesJson:'{}',status:'NONE',publishedAt:''})
const drawer=ref(false),detail=ref<any>(null),selectionOpen=ref(false),selectionProduct=ref<Product|null>(null)
const form=reactive({owner:'',status:'SELECTED',referenceVersionId:undefined as string|undefined,selectedOn:'',startedOn:'',finishedOn:'',note:''})
const researchModes=['opinions','families','catalog','research','materials','planning','experiments','strategy']
const catalogModes=['sources','scope','collection','tasks','runs','alerts','provenance']
const menus=[{group:'市场洞察',icon:Grid,items:[{id:'overview',name:'市场概览',icon:DataAnalysis},{id:'rankings',name:'榜单观察',icon:TrendCharts},{id:'opinions',name:'玩家评价与舆情',icon:Document},{id:'families',name:'玩法与赛道',icon:Grid}]},{group:'产品研究',icon:List,items:[{id:'products',name:'产品情报库',icon:List},{id:'identity',name:'产品关联与核验',icon:Select},{id:'provenance',name:'信息来源与证据',icon:Document}]},{group:'机会与验证',icon:Select,items:[{id:'reports',name:'每周精选',icon:Document},{id:'selections',name:'选用与测试记录',icon:Select},{id:'experiments',name:'验证反馈',icon:Operation}]},{group:'数据采集',icon:Cpu,items:[{id:'capture',name:'信息抓取',icon:Cpu},{id:'scope',name:'信息范围与字段',icon:List},{id:'sources',name:'数据源管理',icon:Setting},{id:'rules',name:'采集规则与计划',icon:Operation},{id:'collection',name:'工具与接入',icon:Cpu},{id:'tasks',name:'采集任务',icon:Document},{id:'runs',name:'执行日志',icon:Document},{id:'alerts',name:'异常与补采',icon:Operation}]},{group:'系统配置',icon:Setting,items:[{id:'strategy',name:'研究目标与推荐',icon:Operation},{id:'materials',name:'研究材料与补证',icon:Document},{id:'planning',name:'旧版采集规划',icon:Setting}]}]
const title=computed(()=>active.value==='profile'?'游戏情报档案':menus.flatMap(m=>m.items).find(m=>m.id===active.value)?.name||'产品库')
const platformLabel:Record<string,string>={WECHAT:'微信',DOUYIN:'抖音',IOS:'iOS',GOOGLE_PLAY:'Google Play'}
const regionLabel:Record<string,string>={CN:'中国',US:'美国',GB:'英国',DE:'德国',FR:'法国'}
const stateLabel:Record<string,string>={COMPLETE:'请求范围完整',PARTIAL:'部分覆盖',FORMAL:'正式库',OBSERVING:'观察中',PENDING_IDENTIFICATION:'待识别',EXCLUDED:'已排除',MISSING_SNAPSHOT:'当日缺失',NOT_IN_COVERAGE:'未在覆盖内',PARTIAL_COVERAGE:'覆盖不全',OBSERVED:'已观察'}
const versionChoices=computed(()=>[...new Map(selectionProduct.value?.rankings.map(r=>[r.versionId,r])||[]).values()])
const currentChart=computed(()=>charts.value.find(c=>String(c.id)===selectedChart.value))
const availableCharts=computed(()=>charts.value.filter(c=>(!chartPlatform.value||c.platform===chartPlatform.value)&&(!chartType.value||c.chart_type===chartType.value)))
const syncStatus=computed(()=>{const s=coverage.value.market?.sync;const seen=s?.heartbeat?.seenAt;if(!seen)return '同步执行器尚未上报';return Date.now()-Date.parse(seen)>300000?'执行器超过5分钟未上报':s.heartbeat.state==='SYNCING'?'正在同步':'执行器在线 · 等待新批次'})
const deliveryLabel:Record<string,string>={COMPLETE:'全部成功',PARTIAL:'部分覆盖',SOURCE_FAILED:'来源失败',INGESTED_REPORT_FAILED:'已入库，周报生成待重试'}
const visibleReports=computed(()=>reportData.value.items.filter((r:any)=>reportGroup.value==='ALL'||(reportGroup.value==='DOMESTIC'?facts(r).region==='CN':facts(r).platform==='GOOGLE_PLAY')))
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())
const disabledDate=(d:Date)=>d>new Date(`${today()}T23:59:59`)
let loadVersion=0,chartLoadVersion=0
async function load(){const token=++loadVersion;++chartLoadVersion;loading.value=true;error.value='';try{
 if(active.value==='capture'){history.replaceState(null,'','#/capture');return}
 if(!filters.date){coverage.value=await getCoverage('');filters.date=coverage.value.date}
 const day=filters.date
 if(active.value==='overview'){const [stat,cov]=await Promise.all([getStats(day),getCoverage(day)]);if(token!==loadVersion)return;stats.value=stat;coverage.value=cov;loadDossierStats(day,token)}
 else if(active.value==='products'){const [products,stat,cov]=await Promise.all([getProfileProducts({...filters,pageSize:20}),getStats(day),getCoverage(day)]);if(token!==loadVersion)return;data.value=products;stats.value=stat;coverage.value=cov}
 else if(active.value==='rankings'){const cov=await getCoverage(day);if(token!==loadVersion)return;coverage.value=cov;charts.value=cov.charts;if(!charts.value.some(c=>String(c.id)===selectedChart.value))selectedChart.value=String(charts.value[0]?.id||'');await loadChart()}
 else if(active.value==='reports'){const request=++reportRequest;const report=reportId.value?await getReport(reportId.value):await getLatestReport();if(token===loadVersion&&request===reportRequest){reportData.value=report;reportId.value=report.id||''}}
 else if(active.value==='selections')selectionData.value=await getSelections({page:1,pageSize:50})
 else if(active.value==='collection'){Object.assign(aiConfig,await getAiConfig());collectionStatus.value=await getInsightCollection(day)}
 else if(active.value==='rules')Object.assign(ruleData,await getCurrentRule())
 if(token===loadVersion)syncUrl()
}catch(e:any){if(token===loadVersion)error.value=e.message}finally{if(token===loadVersion)loading.value=false}}
async function loadChart(){const token=++chartLoadVersion,id=selectedChart.value,day=filters.date,c=currentChart.value;rankingData.value={items:[]};try{const result=c?.external?await getMarketRankings(id,day):c?await getRankings(id,day):{items:[]};if(token!==chartLoadVersion||id!==selectedChart.value||day!==filters.date)return;rankingData.value=result;syncUrl()}catch(e:any){if(token===chartLoadVersion)error.value=e.message}}
function chooseChart(id:string){selectedChart.value=id;chartPlatform.value='';chartType.value='';loadChart()}
function filterCharts(){selectedChart.value=String(availableCharts.value[0]?.id||'');loadChart()}
function syncUrl(){const q=new URLSearchParams();if(active.value==='profile'){Object.entries(profileScope).forEach(([k,v])=>v&&q.set(k,v))}else{Object.entries(filters).forEach(([k,v])=>v&&q.set(k,String(v)));if(active.value==='rankings'&&selectedChart.value)q.set('chart',selectedChart.value);if(active.value==='reports'&&reportId.value)q.set('reportId',reportId.value)}history.replaceState(null,'',`#/${active.value}?${q}`)}
function nav(id:string){if(id!==active.value)history.pushState(null,'',`#/${id}`);active.value=id;load()}
function profileNavigate(scope:{listing:string;date:string;tab:string}){Object.assign(profileScope,scope);syncUrl()}
function backToList(){location.hash=returnUrl}
async function loadDossierStats(day:string,token:number){dossierStatsBusy.value=true;dossierStats.value=null;dossierStatsError.value='';try{let page=await getProfileProducts({date:day,page:1,pageSize:100});if(page.total>2000)throw new Error('档案超过2000款，请在产品库限定范围查看；概览不展示部分聚合数');const rows=[...page.items];for(let p=2;p<=Math.ceil(page.total/100);p++){page=await getProfileProducts({date:day,page:p,pageSize:100});rows.push(...page.items)}if(token!==loadVersion)return;dossierStats.value={products:rows.length,eligible:rows.filter(r=>r.qualification?.eligible).length,unknown:rows.filter(r=>!r.qualification?.eligible).length,readable:rows.reduce((n,r)=>n+Number(r.profileCoverage?.readable||0),0),applicable:rows.reduce((n,r)=>n+Number(r.profileCoverage?.applicable||0),0),drafts:rows.reduce((n,r)=>n+Number(r.profileCoverage?.aiDrafts||0),0)}}catch(e:any){if(token===loadVersion)dossierStatsError.value=e.message}finally{if(token===loadVersion)dossierStatsBusy.value=false}}
function exportProductPage(){const rows=[['产品ID','名称','参考平台','市场','资格','有资料项','适用项','AI草案','待补项','知识日期'],...data.value.items.map((r:any)=>[r.id,r.name,r.referencePlatform,r.referenceMarket,r.qualification?.label,r.profileCoverage?.readable,r.profileCoverage?.applicable,r.profileCoverage?.aiDrafts,r.profileCoverage?.missing,filters.date])];const csv='\uFEFF'+rows.map(row=>row.map((v:any)=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`产品档案-${filters.date}-第${filters.page}页.csv`;a.click();URL.revokeObjectURL(url)}
function addDays(day:string,offset:number){const d=new Date(`${day}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
function shiftDate(offset:number){filters.date=addDays(filters.date,offset);filters.page=1;load()}
async function latestDate(){const c=await getCoverage('');filters.date=c.latestAvailableDate||c.date;load()}
function clear(){Object.assign(filters,{q:'',platform:'',region:'',poolState:'',selectionState:'',qualification:'',gap:'',chartId:'',page:1});load()}
function changeState(state:string){filters.poolState=state;filters.page=1;load()}
function facts(row:any){try{return typeof row.frozen_facts==='string'?JSON.parse(row.frozen_facts):row.frozen_facts||{}}catch{return {}}}
function ranks(row:Product){const matches=row.rankings.filter(r=>(!filters.platform||r.platform===filters.platform)&&(!filters.region||r.region===filters.region));const observed=matches.filter(r=>r.rank!=null);return observed.length?observed:matches}
function rankText(r:Ranking){return r.rank!=null?`#${r.rank}`:stateLabel[r.dataState]||'—'}
function deltaText(r:Ranking){return r.delta7d===null?'—':r.delta7d>0?`↑ ${r.delta7d}`:r.delta7d<0?`↓ ${-r.delta7d}`:'持平'}
function openDetail(p:any,version?:string,market?:string){const day=active.value==='reports'?(reportCoverage.value.asOfDate||addDays(String(reportData.value.periodEnd),-1)):filters.date;returnUrl=location.hash;sessionStorage.setItem('profileReturnUrl',returnUrl);Object.assign(profileScope,{product:String(typeof p==='string'?p:p.id),listing:version?'':String(p.referenceListingId||''),version:version||'',market:market||'',date:day,tab:'overview'});history.pushState(null,'','#/profile');active.value='profile';syncUrl()}
function openReportDetail(id:string){const row=reportData.value.items.find((r:any)=>String(r.product_id)===String(id)||String(facts(r).productId)===String(id));const f=facts(row||{});openDetail(String(id),String(f.main_reference_version_id||f.versionId||row?.main_reference_version_id||''),f.region||'')}
function openSelection(p:Product){selectionProduct.value=p;Object.assign(form,{owner:'',status:'SELECTED',referenceVersionId:undefined,selectedOn:filters.date,startedOn:'',finishedOn:'',note:''});selectionOpen.value=true}
async function selectReport(id:string){const p=await getProduct(id,reportCoverage.value.asOfDate||filters.date);openSelection({...p,selectionSummary:{total:0,inProgress:0,completed:0}})}
async function saveSelection(){if(!selectionProduct.value||!form.owner.trim()){ElMessage.warning('请填写负责人');return}try{await createSelection(selectionProduct.value.id,{...form,referenceVersionId:form.referenceVersionId||null,startedOn:form.startedOn||null,finishedOn:form.finishedOn||null});ElMessage.success('选用记录已保存');selectionOpen.value=false;await load()}catch(e:any){ElMessage.error(e.message)}}
async function saveAi(){try{Object.assign(aiConfig,await saveAiConfig({...aiConfig,apiKey:aiConfig.apiKey||undefined}),{apiKey:''});ElMessage.success('AI 配置已保存')}catch(e:any){ElMessage.error(e.message)}}
async function createWeeklyReport(){
 if(generating.value||openingReport.value)return
 if(!/^\d{4}-\d{2}-\d{2}$/.test(filters.date)){reportActionError.value=true;reportAction.value='请选择有效的分析截止日';return}
 const date=filters.date,request=++reportRequest;generating.value=true;reportActionError.value=false;reportAction.value='正在校验材料并生成精选，请稍候；输入未变化时会复用已保存报告。'
 try{const day=new Date(`${date}T00:00:00Z`).getUTCDay();const report=await generateReport(addDays(date,-((day+6)%7)),addDays(date,1));
  if(request!==reportRequest)return
  reportData.value=report;reportId.value=String(report.id);auditPage.value=1;reportGroup.value='ALL'
  reportAction.value=(report.reused?'生成检查完成：输入未变化，已复用':'生成完成：已保存')+`报告 #${report.id} · 修订 ${report.revision}，${report.researchLeads?.items?.length||0} 条待核研究线索、${report.items?.length||0} 条正式候选。`
  if(active.value==='reports')syncUrl()
 }catch(e:any){if(request===reportRequest){reportActionError.value=true;reportAction.value=`生成未完成：${e.message}。当前显示的已保存报告未被改写；可打开历史周报核对后重试。`}}
 finally{generating.value=false}
}
async function showHistory(){
 historyOpen.value=true;historyLoading.value=true;historyError.value='';const request=++historyRequest
 try{const result=await getReportHistory(historyPage.value);if(request===historyRequest)reportHistory.value=result}
 catch(e:any){if(request===historyRequest)historyError.value=`历史周报加载失败：${e.message}`}
 finally{if(request===historyRequest)historyLoading.value=false}
}
async function chooseReport(id:string){
 if(openingReport.value||generating.value)return
 const request=++reportRequest;openingReport.value=String(id);historyError.value=''
 try{const report=await getReport(String(id));if(request!==reportRequest)return
  reportData.value=report;reportId.value=String(id);auditPage.value=1;reportGroup.value='ALL';filters.date=addDays(String(report.periodEnd),-1)
  reportActionError.value=false;reportAction.value=`已打开历史报告 #${id} · 修订 ${report.revision}；展示当时冻结内容。`;historyOpen.value=false
  if(active.value==='reports'){syncUrl();await nextTick();window.scrollTo({top:0,behavior:'instant'})}
 }catch(e:any){if(request===reportRequest)historyError.value=`报告 #${id} 加载失败：${e.message}。可重试，当前报告保持不变。`}
 finally{openingReport.value=''}
}
async function showSkill(){try{skillData.value=reportData.value.skillSnapshot||await getReportSkill();skillOpen.value=true}catch(e:any){ElMessage.error(e.message)}}
async function collectSources(){collecting.value=true;try{const result=await runInsightCollection();collectionStatus.value=await getInsightCollection(filters.date);ElMessage[result.attempts.some((a:any)=>a.status==='FAILED')?'warning':'success']('采集尝试已记录，请查看来源日期与结果')}catch(e:any){ElMessage.error(e.message)}finally{collecting.value=false}}
async function publishCurrentRule(){try{Object.assign(ruleData,await publishRule(ruleData.rulesJson));ElMessage.success('规则已发布为新版本')}catch(e:any){ElMessage.error(e.message)}}
async function exportReport(){if(exporting.value)return;exporting.value=true;try{const r=reportData.value.presentation==='PAGE'?await getReport(String(reportData.value.id),true):reportData.value;if(r.researchSnapshot){const u=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`研究周报-${r.id}.json`;a.click();URL.revokeObjectURL(u);return;}const text=`# 游戏研究周报 ${r.periodStart}—${r.periodEnd}\n\n报告 ${r.id} / 修订 ${r.revision}\n国内正式 ${r.domesticCount}，海外正式 ${r.overseasCount}，观察 ${r.observationCount}\n\n`+r.items.map((i:any)=>`## ${facts(i).productName}\n\n${i.content}\n\n来源：${facts(i).sourceUrl}\n证据：${i.evidence_refs}\n`).join('\n')+`\nSkill版本：${r.skillSnapshot?.version||'旧版'}\nSkill哈希：${r.skillSnapshot?.sha256||'无'}\n输入哈希：${r.inputSha256||'无'}\n覆盖：${JSON.stringify(reportCoverage.value)}\n`; const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`周报-${r.id}.md`;a.click();URL.revokeObjectURL(url)}catch(e:any){ElMessage.error(`导出失败：${e.message}`)}finally{exporting.value=false}}
function readRoute(){const [path,query='']=location.hash.replace(/^#\//,'').split('?');if(path==='profile'||menus.flatMap(m=>m.items).some(i=>i.id===path))active.value=path!;else active.value='overview';const params=new URLSearchParams(query);if(active.value==='profile'){Object.assign(profileScope,{product:params.get('product')||'',listing:params.get('listing')||'',version:params.get('version')||'',market:params.get('market')||'',date:params.get('date')||today(),tab:params.get('tab')||'overview'});returnUrl=sessionStorage.getItem('profileReturnUrl')||'#/products';return;}params.forEach((v,k)=>{if(k==='reportId')reportId.value=v;else if(k==='chart')selectedChart.value=v;else if(k in filters)(filters as any)[k]=k==='page'?Math.max(1,Number(v)||1):v});if(authenticated.value)load()}
function sessionExpired(){authenticated.value=false;loginToken.value='';loginError.value='会话已失效，请重新登录'}
async function signIn(){loginBusy.value=true;loginError.value='';try{await loginWorkspace(loginToken.value);loginToken.value='';authenticated.value=true;readRoute()}catch(e:any){loginError.value=e.message}finally{loginBusy.value=false}}
async function connectWorkspace(){accessReady.value=false;accessError.value='';try{authenticated.value=(await workspaceAccess()).authenticated;readRoute()}catch(e:any){accessError.value=e.message}finally{accessReady.value=true}}
onMounted(()=>{window.addEventListener('hashchange',readRoute);window.addEventListener('workspace-login-required',sessionExpired);connectWorkspace()})
onUnmounted(()=>{window.removeEventListener('hashchange',readRoute);window.removeEventListener('workspace-login-required',sessionExpired)})
</script>
<template>
<div v-if="!accessReady" class="access-screen">正在连接工作区…</div>
<div v-else-if="accessError" class="access-screen"><div class="access-card"><h1>暂时无法连接工作区</h1><p>请检查网络或稍后重试。</p><el-alert :title="accessError" type="error" :closable="false"/><el-button type="primary" @click="connectWorkspace">重新连接</el-button></div></div>
<form v-else-if="!authenticated" class="access-screen" @submit.prevent="signIn"><div class="access-card"><h1>锦鲤云 · 工作区登录</h1><p>输入服务器配置的工作区访问口令。</p><el-input v-model="loginToken" type="password" show-password autocomplete="current-password" placeholder="工作区访问口令" aria-label="工作区访问口令"/><el-alert v-if="loginError" :title="loginError" type="error" :closable="false"/><el-button type="primary" native-type="submit" :loading="loginBusy">登录工作区</el-button></div></form>
<div v-else class="shell" :class="{'nav-collapsed':collapsed}">
<header><div class="brand"><span class="brand-symbol">◈</span> 锦鲤云</div><div class="top-nav"><span class="current">IAA 产品情报</span></div><div class="header-spacer"/><span class="header-status"><i/>公开数据验证中</span><button class="mobile-toggle" @click="collapsed=!collapsed" aria-label="切换侧栏"><el-icon><Fold/></el-icon></button></header>
<aside><div v-for="menu in menus" :key="menu.group" class="menu-group"><button class="menu-title" @click="groups[menu.group]=!groups[menu.group]" :aria-expanded="groups[menu.group]"><el-icon><component :is="menu.icon"/></el-icon><span>{{menu.group}}</span><el-icon class="group-arrow"><ArrowDown v-if="groups[menu.group]"/><ArrowRight v-else/></el-icon></button><template v-if="groups[menu.group]"><button v-for="item in menu.items" :key="item.id" :class="['menu-item',{active:active===item.id}]" :title="item.name" @click="nav(item.id)"><el-icon><component :is="item.icon"/></el-icon><span>{{item.name}}</span></button></template></div><div class="sidebar-footer">市场信号，沉淀产品机会<br><small>游探 · 实际数据独立留存</small></div></aside>
<main><div class="crumb">市场情报 / {{(active==='capture'||catalogModes.includes(active))?'数据采集':researchModes.includes(active)?'研究与验证':'市场洞察'}} / {{title}}</div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/>
<GameProfile v-if="active==='profile'" :product="profileScope.product" :listing="profileScope.listing" :version="profileScope.version" :market="profileScope.market" :date="profileScope.date" :tab="profileScope.tab" @back="backToList" @navigate="profileNavigate"/><CaptureWorkspace v-else-if="active==='capture'"/><CollectionCatalog v-else-if="catalogModes.includes(active)" :key="active" :mode="active"/><ResearchWorkspace v-else-if="researchModes.includes(active)" :key="active" :mode="active" :date="filters.date"/><section v-else-if="active==='overview'" class="page">
<div class="page-head"><div><h1>市场概览</h1><p>按指定业务日查看来源覆盖、热度信号和当前需要补证的地方。</p></div><span class="page-status">研究优先级 · 不代表收益预测</span></div>
<div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button><span class="muted">缺失日不回填</span></div>
<div class="overview"><div><label>当日已采集榜单</label><strong>{{coverage.market?.observedCharts??0}} / {{coverage.market?.expectedCharts??30}}</strong><small>微信、抖音、iOS与Google Play独立榜单</small></div><div><label>当日真实排名记录</label><strong>{{coverage.market?.rankingEntries??0}}</strong><small>不是去重游戏数 · <button class="link" @click="nav('products')">查看来源候选</button></small></div><div><label>最近同步</label><strong style="font-size:16px">{{coverage.market?.sync?.latest?.receivedAt||'初始化材料已入库'}}</strong><small>{{deliveryLabel[coverage.market?.sync?.latest?.status]||'尚无同步回执'}} · {{syncStatus}}</small></div><div><label>本周研究</label><strong style="font-size:18px"><button class="link" @click="nav('reports')">查看每周精选 →</button></strong><small>国内流程独立运行，海外缺失不阻塞</small></div></div><div class="overview" v-loading="dossierStatsBusy"><div><label>已知产品档案</label><strong>{{dossierStats?.products??'—'}}</strong><small>截至 {{filters.date}} · 每行参考平台</small></div><div><label>纯IAA有依据</label><strong>{{dossierStats?.eligible??'—'}}</strong><small>目标应用版本独立复核</small></div><div><label>资格待核查 / 不适用</label><strong>{{dossierStats?.unknown??'—'}}</strong><small>混变、未知、冲突、过期均不冒充纯IAA</small></div><div><label>当前可读资料量</label><strong>{{dossierStats?.readable??'—'}} / {{dossierStats?.applicable??'—'}}</strong><small>含AI草案 {{dossierStats?.drafts??'—'}} 项；非机会分</small></div></div><el-alert v-if="dossierStatsError" :title="dossierStatsError" type="warning" :closable="false"/>
<el-alert v-if="coverage.market?.sync?.['source-session']?.status==='LOGIN_REQUIRED' || (coverage.market?.sync?.['source-session']?.reviewAfter && Date.now()>=Date.parse(coverage.market.sync['source-session'].reviewAfter))" title="引力引擎登录需要维护：请进入「数据采集 → 信息抓取」查看续登说明。已有快照和周报保留。" type="warning" show-icon :closable="false"/>
<div class="data-panel insight-panel"><div class="section-heading"><h2>来源覆盖与研究边界</h2><button class="link" @click="nav('rankings')">查看榜单观察 →</button></div><p class="muted">热度榜、免费榜和买量来源分开记录；不同平台、国家和日期不综合排名。</p><el-table :data="coverage.charts||[]" size="small"><el-table-column label="平台 / 地区" min-width="150"><template #default="{row}">{{platformLabel[row.platform]||row.platform}} · {{regionLabel[row.region]||row.region}}</template></el-table-column><el-table-column prop="name" label="榜单" min-width="220"/><el-table-column label="状态" width="120"><template #default="{row}"><span :class="['status-tag',row.data_state==='COMPLETE'?'formal':'watch']">{{stateLabel[row.data_state]||row.data_state||'未采集'}}</span></template></el-table-column><el-table-column label="实际条数" width="100"><template #default="{row}">{{row.actual_count??'—'}}</template></el-table-column><el-table-column label="研究解释" min-width="260"><template #default="{row}">{{row.data_state==='MISSING_SNAPSHOT'?'来源缺失：不能当作榜外':row.completeness==='PARTIAL'?'部分覆盖：增长和持续性保持范围':'可用于同口径观察'}}</template></el-table-column></el-table></div>
<div class="workflow"><span>① 采集材料</span><i/><span>② 身份 / IAA / 玩法证据</span><i/><strong>③ 六维范围与分层推荐</strong><i/><span>④ 原型验证与反馈回收</span></div>
</section>
<IdentityWorkspace v-else-if="active==='identity'" :date="filters.date"/>
<section v-else-if="active==='products'" class="page"><div class="state-tabs"><button :class="{active:productView==='sources'}" @click="productView='sources'">全部来源候选</button><button :class="{active:productView==='profiles'}" @click="productView='profiles'">已关联身份档案</button></div><SourceCandidates v-if="productView==='sources'" :date="filters.date" :initial-query="filters.q" :initial-platform="filters.platform" @date-change="filters.date=$event;syncUrl()"/><div v-else>
<div class="page-head"><div><h1>产品库</h1><p>持续积累市场表现，追溯入选依据，记录产品选用情况。</p></div><el-button @click="exportProductPage" :disabled="!data.items.length">导出本页 CSV</el-button></div>
<div class="overview"><div><label>收录产品</label><strong>{{stats.collected??'—'}}</strong><small>截至 {{filters.date}} 已观察产品</small></div><div><label>正式入库</label><strong>{{stats.formal??'—'}}</strong><small>须有版本级 IAA 证据与规则命中</small></div><div><label>当日首次观察</label><strong>{{stats.firstObserved??'—'}}</strong><small>首次观察不等于新上线</small></div><div><label>选用记录</label><strong>{{stats.selections??'—'}}</strong><small>当前多人独立填报记录</small></div></div>
<div class="workflow"><span>① 榜单材料采集</span><i/><span>② 玩法与证据核验</span><i/><strong>③ 产品入库与挑选</strong><i/><span>④ 每周精选报告</span></div>
<div class="data-panel"><div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button><span class="muted">榜单缺日不回填</span></div>
<form class="filterbar" @submit.prevent="filters.page=1;load()"><el-input v-model="filters.q" placeholder="产品名称" clearable/><el-select v-model="filters.platform" placeholder="全部平台" clearable @change="filters.chartId=''" aria-label="产品平台"><el-option v-for="(label,key) in platformLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="filters.region" placeholder="全部地区" clearable @change="filters.chartId=''" aria-label="产品地区"><el-option v-for="(label,key) in regionLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="filters.qualification" placeholder="全部变现资格" clearable aria-label="变现资格"><el-option label="纯IAA有依据" value="IAA"/><el-option label="变现待核查" value="unknown"/><el-option label="混合 / 内购" value="mixed"/><el-option label="证据冲突" value="conflict"/><el-option label="需重新核查" value="stale"/></el-select><el-select v-model="filters.gap" placeholder="全部资料状态" clearable aria-label="资料缺口"><el-option label="有待补资料" value="missing"/><el-option label="冲突或失效" value="conflict_stale"/></el-select><el-select v-model="filters.chartId" :disabled="!filters.platform||!filters.region" placeholder="按首次发现排序" clearable aria-label="单榜排序"><el-option v-for="c in productCharts" :key="c.id" :value="String(c.id)" :label="'按名次 · '+c.name"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="clear">重置</el-button></form>
<div v-if="['WECHAT','DOUYIN'].includes(filters.platform)" class="source-note">小游戏公开页面缺少可核验的平台身份，目前保存在榜单观察中。<button class="link" @click="selectedChart='public-'+filters.platform;nav('rankings')">查看{{platformLabel[filters.platform]}}公开榜单 →</button></div><div class="table-caption"><span>共 {{data.total}} 款产品 · 数据日期：{{filters.date}}</span><span class="muted">不同平台、地区、榜单名次独立</span></div>
<div class="table-wrap"><el-table v-loading="loading" :data="data.items" row-key="id" border><el-table-column type="expand"><template #default="{row}"><p class="muted">所有平台版本与独立榜单；点击名次进入对应平台市场。</p><div v-for="r in row.rankings" :key="`${r.versionId}-${r.chartId}`" class="version-expand"><button class="link" @click="openDetail(row,String(r.versionId),r.region)">{{platformLabel[r.platform]}} · {{regionLabel[r.region]}} · {{r.chartName}} · {{rankText(r)}}</button><span class="muted">{{r.dataState}}</span></div></template></el-table-column><el-table-column label="产品名称 / 核心玩法" min-width="250"><template #default="{row}"><div class="product-cell"><GameIcon :url="row.thumbnailUrl" :name="row.name"/><div><button class="link" @click="openDetail(row)">{{row.name}}</button><div class="muted">{{row.summary||'玩法待核验'}} · 首次观察 {{row.firstObservedDate?.slice(0,10)}}</div></div></div></template></el-table-column><el-table-column label="各平台独立排名" min-width="220"><template #default="{row}"><div v-for="r in ranks(row)" :key="`${r.versionId}-${r.chartId}`" class="rank-line"><button class="link" @click="openDetail(row,String(r.versionId),r.region)" :title="r.chartName||''">{{platformLabel[r.platform]}} {{regionLabel[r.region]}} {{rankText(r)}}</button><small class="muted"> · 7日 {{deltaText(r)}}</small></div></template></el-table-column><el-table-column label="变现依据 / 参考平台" min-width="190"><template #default="{row}"><el-tag :type="row.qualification?.eligible?'success':'warning'">{{row.qualification?.label||'待核查'}}</el-tag><div class="muted">参考 {{platformLabel[row.referencePlatform]}} · {{regionLabel[row.referenceMarket]}}</div></template></el-table-column><el-table-column label="资料量与缺口" min-width="185"><template #default="{row}"><div>{{row.profileCoverage?.readable??0}} / {{row.profileCoverage?.applicable??81}} 项有资料</div><div class="muted">AI草案 {{row.profileCoverage?.aiDrafts??0}} · 待补 {{row.profileCoverage?.missing??81}}</div><small>资料量不代表机会分</small></template></el-table-column><el-table-column label="选用情况" width="110"><template #default="{row}">{{row.selectionSummary.total}} 条记录<div class="muted">{{row.selectionSummary.inProgress}} 制作中</div></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">查看档案</el-button><el-button link type="primary" @click="openDetail(row);profileScope.tab='records';syncUrl()">选用</el-button></template></el-table-column><template #empty><div class="empty">截至该日暂无匹配档案；缺失排名不会用其他日期回填。</div></template></el-table></div><div class="pager"><span>每页 20 款 · {{data.referenceScope}}</span><el-pagination v-model:current-page="filters.page" layout="prev,pager,next" :page-size="20" :total="data.total" @current-change="load"/></div></div></div></section>
<section v-else-if="active==='rankings'" class="page"><div class="page-head"><div><h1>榜单观察</h1><p>玩家热度与买量信号分别记录，不同平台、国家、榜单之间不直接比较名次。</p></div></div>
<div class="notice-band">微信3榜、抖音4榜、iOS中国免费/付费/畅销3榜，以及Google Play美英德法五类榜单独立查看；Google数据来自AppBrain第三方公开表，缺行不补齐。</div><div class="data-panel"><div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button></div><div class="filterbar"><el-select v-model="chartPlatform" placeholder="全部平台" clearable @change="filterCharts"><el-option v-for="(label,key) in platformLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="chartType" placeholder="全部榜单口径" clearable @change="filterCharts"><el-option label="人气 / 热门榜" value="POPULARITY"/><el-option label="免费榜" value="FREE"/><el-option label="付费榜" value="PAID"/><el-option label="新免费游戏" value="NEW_FREE"/><el-option label="新付费游戏" value="NEW_PAID"/><el-option label="畅销榜" value="BESTSELLER"/><el-option label="新游榜" value="NEW"/><el-option label="发行人热度" value="PROMOTION"/></el-select><el-select v-model="selectedChart" class="chart-select" placeholder="请选择榜单" @change="loadChart"><el-option v-for="chart in availableCharts" :key="chart.id" :value="String(chart.id)" :label="`${regionLabel[chart.region]} · ${chart.name}`"/></el-select><el-button @click="load">刷新</el-button></div></div>
<div class="platform-tabs"><button v-for="c in availableCharts" :key="c.id" :class="{active:selectedChart===String(c.id)}" @click="chooseChart(String(c.id))">{{platformLabel[c.platform]}} · {{c.name}}<span>{{regionLabel[c.region]}} · {{c.actual_count||0}} 条 · {{c.data_state==='COMPLETE'?'Top100完整':c.actual_count?'部分覆盖':'当日缺失'}}</span></button></div>
<div class="ranking-panel"><div class="section-heading"><h2>{{currentChart?.name||'暂无匹配榜单'}}</h2><span class="muted">{{filters.date}} · {{rankingData.items.length}} 条</span><a v-if="currentChart?.sourceUrl" :href="currentChart.sourceUrl" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></div><div v-if="currentChart?.external" class="source-note">{{rankingData.notice}} <span v-if="currentChart.platform==='GOOGLE_PLAY'">AppBrain第三方公开榜单；安装量为来源估算，不代表已核实日活或收入。</span><span v-else-if="currentChart.platform!=='IOS'">引力引擎第三方榜单，平台身份待核验。</span></div><div class="table-wrap"><el-table v-loading="loading" :data="rankingData.items" border><el-table-column label="平台 / 地区" width="155"><template #default>{{platformLabel[currentChart?.platform]}} {{regionLabel[currentChart?.region]}}</template></el-table-column><el-table-column label="产品" min-width="340"><template #default="{row}"><div class="product-cell"><GameIcon :url="row.thumbnail_url" :name="row.product_name"/><div><button v-if="row.product_id" class="link" @click="openDetail(String(row.product_id),String(row.version_id),currentChart?.region)">{{row.product_name}}</button><a v-else :href="`#/products?date=${filters.date}&platform=${currentChart?.platform}&q=${encodeURIComponent(row.product_name)}`">{{row.product_name}}</a><div class="muted">{{row.developer||'平台独立版本'}}<span v-if="row.tags"> · {{row.tags.join(' / ')}}</span></div></div></div></template></el-table-column><el-table-column label="名次" width="90"><template #default="{row}"><span :class="['rank-number',{top:row.rank<=3}]">#{{row.rank}}</span></template></el-table-column><el-table-column label="业务日期" width="130"><template #default>{{filters.date}}</template></el-table-column><el-table-column label="覆盖状态" width="130"><template #default="{row}"><span :class="['status-tag',row.completeness==='COMPLETE'?'formal':'watch']">{{row.completeness==='COMPLETE'?'完整覆盖':'部分覆盖'}}</span></template></el-table-column><el-table-column label="来源 / 身份" min-width="210"><template #default="{row}">{{currentChart?.platform==='IOS'?'Apple 游戏分类 RSS':currentChart?.platform==='GOOGLE_PLAY'?'AppBrain · Google Play':'引力引擎 · 身份待核验'}}<div class="muted">{{row.observationId?`来源观察 ${row.observationId}`:row.snapshot_id?`快照 ${row.snapshot_id}`:'身份待核验'}}</div></template></el-table-column><template #empty><div class="empty">该日期暂无快照，不回填其它日期数据。</div></template></el-table></div></div></section>
<section v-else-if="active==='reports'" class="page reports-page">
<div class="page-head"><div><h1>每周精选</h1><p>{{reportData.periodStart}} — {{reportData.periodEnd}}（不含结束日） · 修订 {{reportData.revision||'—'}} · 生成于 {{generatedTime}}</p></div><div class="head-actions"><el-button @click="showSkill">精选 Skill</el-button><el-button :disabled="!reportData.id" :loading="exporting" @click="exportReport">导出周报</el-button></div></div>
<div class="report-generation"><span>分析截止日</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" :clearable="false" :disabled-date="disabledDate"/><el-button type="primary" :loading="generating" :disabled="!!openingReport" @click="createWeeklyReport">{{generating?'正在生成…':'生成本周精选'}}</el-button><el-button :loading="historyLoading" @click="showHistory">历史周报</el-button><span class="muted">从本周一到截止日；相同输入复用，变化后新增修订。</span></div>
<div class="report-result" :class="{failed:reportActionError}" role="status" aria-live="polite"><b>{{reportSummary}}</b><p v-if="reportAction">{{reportAction}}</p><p v-else-if="researchCount">本期研究线索已生成，请查看下方入选理由与来源。纯IAA正式候选需补足版本级证据。</p></div>
<div class="notice-band">{{reportData.skillSnapshot?'按冻结方案目标数量，不足不凑数':'历史报告保留冻结内容'}} · 正式IAA {{(reportData.domesticCount||0)+(reportData.overseasCount||0)}} · 待核研究线索 {{reportData.researchLeads?.items?.length||0}} · 市场观察 {{reportData.observationCount||0}}。热度不等于增长，研究优先级不等于盈利概率。</div>
<details v-if="reportData.id" class="insight-panel"><summary>数据覆盖与筛选依据 · {{reportData.skillSnapshot?.version||'历史规则'}}</summary><p>{{reportCoverage.policy}}</p><p>{{reportCoverage.shortfallReason}}</p><el-table :data="reportCoverage.sources||[]" size="small"><el-table-column label="来源 / 榜单" min-width="240"><template #default="{row}">{{row.source_name}} · {{row.name}}</template></el-table-column><el-table-column label="近14日覆盖" width="130"><template #default="{row}">{{row.observedDays??row.observed_days}} / {{row.windowDays||'—'}}</template></el-table-column><el-table-column label="7日对比条件" width="140"><template #default="{row}">{{row.delta7dReady?'两端快照齐全':'缺少对比快照'}}</template></el-table-column><el-table-column label="缺失日期" min-width="200"><template #default="{row}">{{row.missingDates?.join('、')||'—'}}</template></el-table-column></el-table><p v-for="p in reportCoverage.publicObservations||[]" :key="p.platform">{{platformLabel[p.platform]}}：{{p.actual_count}} 条公开观察，{{p.reason}}</p><p>{{reportCoverage.historyNotice}}</p><a v-if="reportData.fullEvidenceUrl" :href="reportData.fullEvidenceUrl" target="_blank" rel="noopener noreferrer">查看完整冻结证据 JSON（文件较大，按需打开） ↗</a></details>
<div class="report-tabs state-tabs"><button v-for="t in [['ALL','全部候选'],['DOMESTIC','国内'],['OVERSEAS','海外']]" :key="t[0]" :class="{active:reportGroup===t[0]}" @click="reportGroup=t[0]!">{{t[1]}}</button></div><div v-if="reportData.message" class="empty">{{reportData.message}}</div><p v-else-if="!visibleReports.length" class="report-qualification-note">{{visibleResearchCount?`当前范围有 ${visibleResearchCount} 条待核研究线索，详见下方；暂无通过纯IAA资格的正式候选。`:'当前范围没有符合条件的候选；可切换范围或查看筛选缺口。'}}</p><div v-else class="report-grid"><ReportCard v-for="row in visibleReports" :key="row.id" :row="row" @detail="id=>openReportDetail(String(id))" @select="id=>selectReport(String(id))"/></div>
<ResearchLeadList v-if="reportData.researchLeads" :report="reportData.researchLeads" :group="reportGroup" :report-id="String(reportData.id)"/>
<div v-if="reportData.researchSnapshot" class="insight-panel"><h3>本期诊断与补证 · 全候选保留</h3><p>{{reportData.researchSnapshot.result.diagnostic}}</p><p>可用材料截止（UTC）：{{reportData.availableCutoff}} · 规则结果已冻结；AI未调用。</p><el-table :data="(reportData.researchSnapshot.result.rows||[]).slice((auditPage-1)*20,auditPage*20)" border><el-table-column prop="name" label="候选" min-width="180"/><el-table-column label="层级" width="110"><template #default="{row}">{{({ready:'重点验证',conditional:'条件推荐',lead:'线索推荐',paused:'暂缓验证',excluded:'范围不匹配'} as any)[row.route]}}</template></el-table-column><el-table-column label="范围 / 覆盖" width="160"><template #default="{row}">{{row.utilityRange.lower.toFixed(1)}}～{{row.utilityRange.upper.toFixed(1)}}<div class="muted">输入覆盖 {{(row.inputCoverage*100).toFixed(1)}}%</div></template></el-table-column><el-table-column label="行动与缺口" min-width="300"><template #default="{row}">{{row.action}}<div class="muted">{{row.unselectedReason||row.slot}}</div><details><summary>补证与逐维依据</summary><p v-for="t in row.evidenceTasks" :key="t.key">{{t.label}} · {{t.impact===null?'前提优先':`最多缩小 ${t.impact.toFixed(2)} 分`}}</p><p v-for="r in row.dimensions" :key="r.key">{{r.key}}：{{r.lower.toFixed(2)}}～{{r.upper.toFixed(2)}} · {{r.status}} · {{r.boundMethod}}</p></details></template></el-table-column><el-table-column label="产品" width="90"><template #default="{row}"><el-button link @click="openDetail(String(row.productId))">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="auditPage" :page-size="20" :total="reportData.researchSnapshot.result.rows.length" layout="prev,pager,next"/></div>
<details v-if="reportData.candidateAudit&&!reportData.researchSnapshot" class="insight-panel"><summary>本期候选审计 · {{reportData.candidateAudit.length}} 条平台地区记录（含去重与淘汰）</summary><el-table :data="auditRows" size="small"><el-table-column prop="product_name" label="产品" min-width="180"/><el-table-column label="平台 / 地区" width="150"><template #default="{row}">{{platformLabel[row.platform]}} / {{row.region}}</template></el-table-column><el-table-column label="研究范围" width="100"><template #default="{row}">{{row.v22?`${Number(row.v22.utilityRange.lower).toFixed(1)}～${Number(row.v22.utilityRange.upper).toFixed(1)}`:'历史记录'}}</template></el-table-column><el-table-column label="结论" min-width="160"><template #default="{row}">{{row.v22?.unselectedReason||row.v22?.action||decisionLabel[row.decision]||row.decision}}</template></el-table-column></el-table><el-pagination v-model:current-page="auditPage" :page-size="20" :total="reportData.candidateAudit.length" layout="prev, pager, next"/></details>
<el-drawer v-model="historyOpen" title="历史周报 · 所有修订" size="min(960px, 96vw)" append-to-body><p class="muted">选择“查看”打开已保存版本；不会重新生成或覆盖历史。</p><el-alert v-if="historyError" :title="historyError" type="error" :closable="false"/><el-button v-if="historyError" @click="showHistory">重新加载历史</el-button><p v-if="historyLoading" role="status">正在加载历史周报…</p><p v-if="openingReport" role="status">正在打开报告 #{{openingReport}}…</p><el-table v-loading="historyLoading" :data="reportHistory.items" :max-height="'calc(100dvh - 270px)'"><el-table-column prop="id" label="报告" width="70"/><el-table-column label="报告期" min-width="220"><template #default="{row}">{{row.period_start}} — {{row.period_end}}</template></el-table-column><el-table-column prop="revision" label="修订" width="65"/><el-table-column prop="item_count" label="正式" width="65"/><el-table-column prop="research_lead_count" label="研究线索" width="90"/><el-table-column label="查看" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" :loading="openingReport===String(row.id)" :disabled="generating||!!openingReport" @click="chooseReport(row.id)">查看</el-button></template></el-table-column></el-table><el-pagination :disabled="historyLoading||!!openingReport" v-model:current-page="historyPage" :page-size="20" :total="reportHistory.total" layout="prev, pager, next" @current-change="showHistory"/></el-drawer>
<el-drawer v-model="skillOpen" title="精选 Skill · 冻结版本" size="min(850px, 96vw)"><p>当前{{reportData.skillSnapshot?'报告生成时保存':'系统默认'}}版本：{{skillData?.version}}</p><p class="muted">Java执行确定性模型；AI未参与本期结论生成。后续变更不会覆盖旧报告。</p><pre class="skill-text">{{skillData?.instructions}}</pre><pre class="skill-text">{{JSON.stringify(skillData?.policy,null,2)}}</pre><p class="hash-text">SHA256：{{skillData?.sha256}}</p></el-drawer>
</section>
<section v-else-if="active==='selections'" class="page"><div class="page-head"><div><h1>选用记录</h1><p>多人记录独立维护，展示当前制作状态。</p></div><el-button type="primary" @click="nav('products')">从产品库新增</el-button></div><div class="table-wrap"><el-table :data="selectionData.items" border><el-table-column prop="id" label="记录ID" width="90"/><el-table-column prop="product_name" label="产品"/><el-table-column prop="owner_name" label="负责人"/><el-table-column prop="status" label="状态"/><el-table-column prop="selected_on" label="选用日期"/><el-table-column prop="note" label="备注"/></el-table></div><SourceCandidates records-only :date="filters.date"/></section>
<section v-else-if="active==='collection'" class="page"><div class="page-head"><div><h1>AI 采集中心</h1><p>配置任意 OpenAI-compatible 中转；API Key 只写入服务端加密字段，读取时不回显。</p></div><el-tag :type="aiConfig.apiKeyConfigured?'success':'warning'">{{aiConfig.apiKeyConfigured?'密钥已配置':'未配置密钥'}}</el-tag></div><div class="insight-panel" v-if="collectionStatus"><div class="section-heading"><h2>市场数据积累</h2><el-button :loading="collecting" @click="collectSources">采集可用免费来源</el-button></div><p>每日采集：{{collectionStatus.dailyEnabled?'已启用（中国时间08:00）':'未启用'}} · 每周留档：{{collectionStatus.weeklyEnabled?'已启用（周一09:00）':'未启用'}} · AppBrain自动取材：{{collectionStatus.appBrainEnabled?'启用':'未启用，需网络可达后配置'}}</p><p class="muted">微信/抖音目前仍需公开渲染材料导入；不声称全平台自动采集。</p><el-table :data="collectionStatus.sources" size="small"><el-table-column prop="name" label="榜单" min-width="200"/><el-table-column label="观察窗来源覆盖" width="160"><template #default="{row}">{{row.observedDays}} / {{row.windowDays||14}}</template></el-table-column><el-table-column prop="currentState" label="所选日期状态" min-width="160"/></el-table><el-table :data="collectionStatus.attempts" size="small" max-height="260"><el-table-column prop="source_key" label="任务"/><el-table-column prop="requested_date" label="尝试日期"/><el-table-column prop="status" label="结果"/><el-table-column prop="result_json" label="结果依据 / 缺口" min-width="260" show-overflow-tooltip/></el-table></div><div class="config-card"><el-form label-width="125px"><el-form-item label="供应商名称"><el-input v-model="aiConfig.providerName" placeholder="例如 Grok / DeepSeek / 公司中转"/></el-form-item><el-form-item label="Base URL"><el-input v-model="aiConfig.baseUrl" placeholder="https://your-proxy.example.com/v1"/></el-form-item><el-form-item label="模型"><el-input v-model="aiConfig.model" placeholder="例如 gpt-4o-mini / deepseek-chat"/></el-form-item><el-form-item label="API Key"><el-input v-model="aiConfig.apiKey" type="password" show-password placeholder="留空表示保持当前密钥"/></el-form-item><el-form-item label="超时（秒）"><el-input-number v-model="aiConfig.timeoutSeconds" :min="5" :max="300"/></el-form-item><el-form-item label="Temperature"><el-input-number v-model="aiConfig.temperature" :min="0" :max="2" :step="0.1"/></el-form-item><el-form-item label="启用"><el-switch v-model="aiConfig.enabled"/></el-form-item><el-button type="primary" @click="saveAi">保存配置</el-button></el-form><div class="config-help"><b>配置格式</b><p>只要中转兼容 <code>/v1/chat/completions</code>，填写 Base URL、模型和 Key 即可。Grok、GPT、DeepSeek 都走同一套字段。</p><p>当前配置可保存，模型调用链尚未验收；候选数字与资格由 Java 校验。</p></div></div></section>
<section v-else-if="active==='rules'" class="page"><div class="page-head"><div><h1>规则配置</h1><p>规则发布会产生新版本；历史周报和旧规则命中不会被覆盖。</p></div><el-tag type="info">当前 v{{ruleData.versionNumber || '—'}}</el-tag></div><div class="config-card"><el-input v-model="ruleData.rulesJson" type="textarea" :rows="16"/><div class="config-help"><p>建议字段：<code>topN</code>、<code>windowDays</code>、<code>sustainedDays</code>、<code>rapidRiseDays</code>、<code>rapidRiseDelta</code>、<code>reportDomesticLimit</code>、<code>reportOverseasLimit</code>。</p><p>当前支持规则版本保存与发布；规则试算及自动市场判定尚未完成。</p></div><el-button type="primary" @click="publishCurrentRule">发布新规则版本</el-button></div></section>
<footer>游探 · Java + MySQL · 名次按来源独立，缺失不回填</footer></main>
<el-dialog v-model="selectionOpen" title="新增选用记录" width="480px"><el-form label-width="90px"><el-form-item label="负责人" required><el-input v-model="form.owner" maxlength="40"/></el-form-item><el-form-item label="参考版本"><el-select v-model="form.referenceVersionId" clearable placeholder="可选"><el-option v-for="r in versionChoices" :key="r.versionId" :label="`${platformLabel[r.platform]||r.platform} · ${r.versionName}`" :value="r.versionId"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="已选" value="SELECTED"/><el-option label="制作中" value="IN_PROGRESS"/><el-option label="已完成" value="COMPLETED"/><el-option label="放弃" value="ABANDONED"/></el-select></el-form-item><el-form-item label="选用日期"><el-date-picker v-model="form.selectedOn" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note" type="textarea" maxlength="1000" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="selectionOpen=false">取消</el-button><el-button type="primary" @click="saveSelection">保存</el-button></template></el-dialog>
</div>
</template>


